exercises.solution:
class Dog:
    def __init__(self, name):
        self.name = name
    def bark(self):
        print(f"{self.name} says woof!")

d = Dog("Bingo")
d.bark()

class BankAccount:
    def __init__(self, owner):
        self.owner = owner
        self.balance = 0
    def deposit(self, amount):
        self.balance = self.balance + amount

acct = BankAccount("Roli")
acct.deposit(50)
print(acct.balance)

